@OptIn(ExperimentalPermissionsApi::class)
@Composable
fun HardwareScreen(
 viewModel: HardwareViewModel = koinViewModel()
) {


 val permissionState = rememberPermissionState(
 permission = android.Manifest.permission.CAMERA
 )
 LaunchedEffect(key1 = Unit) {
 if (permissionState.status.isGranted) {
 viewModel.handleIntent(HardwareContract.Intent.RefreshData)
 } else {
 permissionState.launchPermissionRequest()
 }
 }

 val requestPermissionLauncher =
 rememberLauncherForActivityResult(ActivityResultContracts.RequestPermission()) {
 if (it) {
 viewModel.handleIntent(HardwareContract.Intent.RefreshData)
 } else {
 viewModel.handleIntent(HardwareContract.Intent.ShowPermissionDenied)
 }
 }


 LaunchedEffect(key1 = Unit) {
 if (!permissionState.status.isGranted) {
 requestPermissionLauncher.launch(android.Manifest.permission.CAMERA)
 }
 }


 val state by viewModel.state.collectAsState()




 when {
 state.loadingInfo.isLoading -> {
 LoadingState(message = "Loading hardware information...")
 }

 else -> {


 Column(
 modifier = Modifier
 .fillMaxSize()
 .verticalScroll(rememberScrollState())
 .padding(CoreDroidDimensions.ScreenPadding),
 verticalArrangement = Arrangement.spacedBy(CoreDroidDimensions.SpaceLarge)
 ) {


 when (state.cpuInfoState) {
 UiState.Empty -> {
 CpuCard(cpuInfo = CpuInfo.empty())
 }

 is UiState.Error -> {
 ErrorState(
 message = "Failed to load CPU information",
 onRetry = { viewModel.handleIntent(HardwareContract.Intent.RefreshData) })
 }

 UiState.Loading -> {
 LoadingState(message = "Loading CPU information...")

 }

 is UiState.Success<*> -> {
 val cpu = (state.cpuInfoState as UiState.Success<CpuInfo>).data
 CpuCard(cpuInfo = cpu)
 RamCard(cpuInfo = cpu)
 }
 }


 when (state.displayInfoState) {
 UiState.Empty -> {
 DisplayCard(DisplayInfo.empty())
 }

 is UiState.Error -> {
 ErrorState(
 message = "Failed to load Display information",
 onRetry = { viewModel.handleIntent(HardwareContract.Intent.RefreshData) })
 }

 UiState.Loading -> {
 LoadingState(message = "Loading Display information...")

 }

 is UiState.Success<*> -> {
 val display = (state.displayInfoState as UiState.Success<DisplayInfo>).data
 DisplayCard(displayInfo = display)
 }
 }

 when (state.cameraInfoState) {
 UiState.Empty -> {
 CameraCard(CameraInfo.empty())
 }

 is UiState.Error -> {
 ErrorState(
 message = "Failed to load Camera information",
 onRetry = { viewModel.handleIntent(HardwareContract.Intent.RefreshData) })
 }

 UiState.Loading -> {
 LoadingState(message = "Loading Display information...")

 }

 is UiState.Success<*> -> {
 val camera = (state.cameraInfoState as UiState.Success<CameraInfo>).data
 CameraCard(cameraInfo = camera)
 }
 }
 }
 }
 }
