@OptIn(ExperimentalPermissionsApi::class)
@Composable
fun NetworkScreen(
 viewModel: NetworkViewModel = koinViewModel()
) {
 val state by viewModel.state.collectAsState()
 val context = LocalContext.current
 val permissionManager = PermissionManager(context)

 val phonePermissionState = rememberPermissionState(
 permission = android.Manifest.permission.READ_PHONE_STATE
 )

 val requestPhonePermissionLauncher = rememberLauncherForActivityResult(
 ActivityResultContracts.RequestPermission()
 ) { isGranted ->
 if (isGranted) {
 viewModel.onPhonePermissionGranted()
 } else {
 val isPermanentlyDenied =
 (context as? androidx.activity.ComponentActivity)?.let { activity ->
 permissionManager.isPermissionPermanentlyDenied(
 activity,
 android.Manifest.permission.READ_PHONE_STATE
 )
 } ?: false
 viewModel.onPhonePermissionDenied(isPermanentlyDenied)
 }
 }

 // Handle effects
 LaunchedEffect(Unit) {
 viewModel.effect.collect { effect ->
 when (effect) {
 is NetworkContract.Effect.ShowError -> {
 Toast.makeText(context, effect.message, Toast.LENGTH_LONG).show()
 }

 is NetworkContract.Effect.ShowMonitoringStarted -> {
 Toast.makeText(context, "Real-time monitoring started", Toast.LENGTH_SHORT)
 .show()
 }

 is NetworkContract.Effect.ShowMonitoringStopped -> {
 Toast.makeText(context, "Monitoring stopped", Toast.LENGTH_SHORT).show()
 }

 is NetworkContract.Effect.OpenAppSettings -> {
 val intent = Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS).apply {
 data = Uri.fromParts("package", context.packageName, null)
 }
 context.startActivity(intent)
 }
 }
 }
 }

 // Initial permission check
 LaunchedEffect(key1 = phonePermissionState.status.isGranted) {
 if (phonePermissionState.status.isGranted) {
 viewModel.onPhonePermissionGranted()
 }
 }

 // Handle different UI states properly
 when {
 state.loadingInfo.isLoading -> {
 LoadingState(message = state.loadingInfo.message ?: "Loading...")
 }

 state.networkInfoState.isError -> {
 ErrorState(
 message = state.networkInfoState.getErrorOrNull()?.message ?: "Unknown error",
 onRetry = { viewModel.handleIntent(NetworkContract.Intent.RefreshData) }
 )
 }

 state.networkInfoState.isSuccess -> {
 val networkInfo = state.networkInfoState.getDataOrNull()!!

 Column(
 modifier = Modifier
 .fillMaxSize()
 .verticalScroll(rememberScrollState())
 .padding(CoreDroidDimensions.ScreenPadding),
 verticalArrangement = Arrangement.spacedBy(CoreDroidDimensions.SpaceLarge)
 ) {
 // Monitoring Status Banner (visible when monitoring)
 if (state.isMonitoring) {
 MonitoringStatusBanner()
 }

 // Network Information Cards
 MobileCard(
 networkInfo = networkInfo,
 phonePermissionState = state.phonePermissionState,
 onRequestPermission = {
 requestPhonePermissionLauncher.launch(android.Manifest.permission.READ_PHONE_STATE)
 },
 onOpenAppSettings = {
 viewModel.handleIntent(NetworkContract.Intent.OpenAppSettings)
 }
 )
 WifiCard(networkInfo = networkInfo)
 ConnectivityCard(networkInfo = networkInfo)

 // Monitoring Controls
 MonitoringControls(
 isMonitoring = state.isMonitoring,
 onStartMonitoring = {
 viewModel.handleIntent(NetworkContract.Intent.StartMonitoring)
 },
 onStopMonitoring = {
 viewModel.handleIntent(NetworkContract.Intent.StopMonitoring)
 }
 )

 // Monitoring Events (visible when monitoring and has events)
 if (state.isMonitoring && state.monitoringEvents.isNotEmpty()) {
 MonitoringEventsCard(
 events = state.monitoringEvents,
 onClearEvents = {
 viewModel.handleIntent(NetworkContract.Intent.ClearMonitoringEvents)
 }
 )
 }
 }
 }
 }
}

@Composable
private fun MonitoringStatusBanner() {
 Card(
 modifier = Modifier.fillMaxWidth(),
 colors = CardDefaults.cardColors(
 containerColor = MaterialTheme.colorScheme.primaryContainer
 ),
 elevation = CardDefaults.cardElevation(defaultElevation = CoreDroidDimensions.ElevationSmall)
 ) {
 Row(
 modifier = Modifier.padding(CoreDroidDimensions.SpaceMedium),
 verticalAlignment = Alignment.CenterVertically,
 horizontalArrangement = Arrangement.spacedBy(CoreDroidDimensions.SpaceSmall)
 ) {
 // Animated pulse indicator
 Box(
 modifier = Modifier
 .size(12.dp)
 .clip(CircleShape)
 .background(MaterialTheme.colorScheme.primary)
 )

 Text(
 text = " LIVE MONITORING",
 style = MaterialTheme.typography.titleSmall,
 fontWeight = FontWeight.Bold,
 color = MaterialTheme.colorScheme.onPrimaryContainer
 )

 Spacer(modifier = Modifier.weight(1f))

 Text(
 text = "Tracking network changes",
 style = MaterialTheme.typography.bodySmall,
 color = MaterialTheme.colorScheme.onPrimaryContainer.copy(alpha = 0.8f)
 )
 }
 }
}

@Composable
private fun MonitoringControls(
 isMonitoring: Boolean,
 onStartMonitoring: () -> Unit,
 onStopMonitoring: () -> Unit
) {
 Card(
 modifier = Modifier.fillMaxWidth(),
 elevation = CardDefaults.cardElevation(defaultElevation = CoreDroidDimensions.ElevationMedium)
 ) {
 Column(
 modifier = Modifier.padding(CoreDroidDimensions.CardPadding),
 verticalArrangement = Arrangement.spacedBy(CoreDroidDimensions.SpaceMedium)
 ) {
 Text(
 text = " Real-time Network Monitoring",
 style = MaterialTheme.typography.titleMedium,
 color = MaterialTheme.colorScheme.onSurface
 )

 Text(
 text = if (isMonitoring) {
 "Monitor active - Network changes are being tracked in real-time. Changes will appear below."
 } else {
 "Start monitoring to track WiFi connections, mobile data changes, and connectivity status in real-time."
 },
 style = MaterialTheme.typography.bodyMedium,
 color = MaterialTheme.colorScheme.onSurfaceVariant
 )

 Button(
 onClick = if (isMonitoring) onStopMonitoring else onStartMonitoring,
 modifier = Modifier.fillMaxWidth()
 ) {
 if (isMonitoring) {
 Row(
 verticalAlignment = Alignment.CenterVertically,
 horizontalArrangement = Arrangement.spacedBy(CoreDroidDimensions.SpaceXSmall)
 ) {
 Text("Stop Monitoring")
 }
 } else {
 Text("Start Real-time Monitoring")
 }
 }
 }
 }
}

@Composable
private fun MonitoringEventsCard(
 events: List<NetworkContract.MonitoringEvent>,
 onClearEvents: () -> Unit
) {
 Card(
 modifier = Modifier.fillMaxWidth(),
 elevation = CardDefaults.cardElevation(defaultElevation = CoreDroidDimensions.ElevationMedium)
 ) {
 Column(
 modifier = Modifier.padding(CoreDroidDimensions.CardPadding)
 ) {
 Row(
 modifier = Modifier.fillMaxWidth(),
 horizontalArrangement = Arrangement.SpaceBetween,
 verticalAlignment = Alignment.CenterVertically
 ) {
 Text(
 text = " Network Changes (${events.size})",
 style = MaterialTheme.typography.titleMedium,
 color = MaterialTheme.colorScheme.onSurface
 )

 OutlinedButton(
 onClick = onClearEvents,
 modifier = Modifier.height(32.dp)
 ) {
 Text(
 text = "Clear",
 style = MaterialTheme.typography.bodySmall
 )
 }
 }

 Spacer(modifier = Modifier.height(CoreDroidDimensions.SpaceSmall))

 LazyColumn(
 modifier = Modifier.height(200.dp),
 verticalArrangement = Arrangement.spacedBy(CoreDroidDimensions.SpaceXSmall)
 ) {
 items(events.reversed()) { event ->
 MonitoringEventItem(event = event)
 }
 }
 }
 }
}

@Composable
private fun MonitoringEventItem(event: NetworkContract.MonitoringEvent) {
 val timeFormat = SimpleDateFormat("HH:mm:ss", Locale.getDefault())

 Card(
 modifier = Modifier.fillMaxWidth(),
 colors = CardDefaults.cardColors(
 containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f)
 ),
 shape = RoundedCornerShape(8.dp)
 ) {
 Row(
 modifier = Modifier.padding(CoreDroidDimensions.SpaceSmall),
 verticalAlignment = Alignment.CenterVertically
 ) {
 Text(
 text = timeFormat.format(Date(event.timestamp)),
 style = MaterialTheme.typography.bodySmall,
 color = MaterialTheme.colorScheme.primary,
 fontWeight = FontWeight.Medium,
 modifier = Modifier.width(60.dp)
 )

 Spacer(modifier = Modifier.width(CoreDroidDimensions.SpaceSmall))

 Text(
 text = event.type,
 style = MaterialTheme.typography.bodySmall,
 fontWeight = FontWeight.Medium,
 color = MaterialTheme.colorScheme.onSurfaceVariant,
 modifier = Modifier.width(80.dp)
 )

 Spacer(modifier = Modifier.width(CoreDroidDimensions.SpaceSmall))

 Text(
 text = event.description,
 style = MaterialTheme.typography.bodySmall,
 color = MaterialTheme.colorScheme.onSurfaceVariant,
 modifier = Modifier.weight(1f)
 )
 }
 }
}
