import com.sultonuzdev.coredroid.presentation.theme.CoreDroidTextStyles

@Composable
fun MainNavigation() {
 val navController = rememberNavController()
 var selectedTab by remember { mutableIntStateOf(0) }

 val screens = listOf(
 OverviewRoute to "Overview",
 HardwareRoute to "Hardware",
 SystemRoute to "System",
 NetworkRoute to "Network",
 SensorsRoute to "Sensors"
 )

 Column(
 modifier = Modifier.fillMaxSize()
 ) {
 // App Header
 Box(
 modifier = Modifier
 .fillMaxWidth()
 .background(
 brush = Brush.linearGradient(
 colors = CoreDroidColors.Gradients.SecondaryGradient
 )
 )
 .padding(CoreDroidDimensions.HeaderPadding),
 contentAlignment = Alignment.Center
 ) {
 Column(
 horizontalAlignment = Alignment.CenterHorizontally
 ) {
 Text(
 text = "CoreDroid",
 style = CoreDroidTextStyles.AppTitle,
 color = Color.White
 )
 Text(
 text = "Complete Device Information",
 style = CoreDroidTextStyles.AppSubtitle,
 color = Color.White.copy(alpha = 0.9f)
 )
 }
 }

 // Tab Row
 ScrollableTabRow(
 selectedTabIndex = selectedTab,
 modifier = Modifier.fillMaxWidth(),
 containerColor = MaterialTheme.colorScheme.surfaceVariant,
 contentColor = MaterialTheme.colorScheme.onSurfaceVariant,
 edgePadding = 0.dp
 ) {
 screens.forEachIndexed { index, (screen, title) ->
 Tab(
 selected = selectedTab == index,
 onClick = {
 selectedTab = index
 navController.navigate(screen) {
 popUpTo(navController.graph.startDestinationId) {
 saveState = true
 }
 launchSingleTop = true
 restoreState = true
 }
 },
 modifier = Modifier
 .padding(horizontal = CoreDroidDimensions.TabPadding)
 .clip(RoundedCornerShape(8.dp)),
 selectedContentColor = if (selectedTab == index) {
 Color.White
 } else {
 MaterialTheme.colorScheme.onSurfaceVariant
 },
