import com.sultonuzdev.coredroid.core.navigation.SensorDetailsRoute
import com.sultonuzdev.coredroid.core.navigation.SensorsRoute
import com.sultonuzdev.coredroid.core.navigation.SystemRoute
import com.sultonuzdev.coredroid.presentation.screens.hardware.HardwareScreen
import com.sultonuzdev.coredroid.presentation.screens.network.NetworkMonitoringScreen
import com.sultonuzdev.coredroid.presentation.screens.network.NetworkScreen
import com.sultonuzdev.coredroid.presentation.screens.overview.OverviewScreen
import com.sultonuzdev.coredroid.presentation.screens.sensors.SensorsScreen
import com.sultonuzdev.coredroid.presentation.screens.sensors.details.SensorDetailsScreen
import com.sultonuzdev.coredroid.presentation.screens.system.SystemScreen
import com.sultonuzdev.coredroid.presentation.theme.CoreDroidColors
import com.sultonuzdev.coredroid.presentation.theme.CoreDroidDimensions
import com.sultonuzdev.coredroid.presentation.theme.CoreDroidTextStyles

data class BottomNavItem(
 val route: Any,
 val title: String,
 val icon: ImageVector
)

@Composable
fun MainNavigation() {
 val navController = rememberNavController()
 val navBackStackEntry by navController.currentBackStackEntryAsState()
 val currentDestination = navBackStackEntry?.destination

 val bottomNavItems = listOf(
 BottomNavItem(OverviewRoute, "Overview", Icons.Default.Home),
 BottomNavItem(HardwareRoute, "Hardware", Icons.Default.Memory),
 BottomNavItem(SystemRoute, "System", Icons.Default.Computer),
 BottomNavItem(NetworkRoute, "Network", Icons.Default.Wifi),
 BottomNavItem(SensorsRoute, "Sensors", Icons.Default.Sensors)
 )

 // Get current screen title
 val currentTitle by remember {
 derivedStateOf {
 when {
 currentDestination?.hasRoute<OverviewRoute>() == true -> "Overview"
 currentDestination?.hasRoute<HardwareRoute>() == true -> "Hardware"
 currentDestination?.hasRoute<SystemRoute>() == true -> "System"
 currentDestination?.hasRoute<NetworkRoute>() == true -> "Network"
 currentDestination?.hasRoute<NetworkMonitoringRoute>() == true -> "Network Monitoring"
 currentDestination?.hasRoute<SensorsRoute>() == true -> "Sensors"
 currentDestination?.hasRoute<SensorDetailsRoute>() == true -> "Sensor Details"
 else -> "CoreDroid"
 }
 }
 }

 // Determine if bottom bar should be shown
 val shouldShowBottomBar by remember {
 derivedStateOf {
 when {
 currentDestination?.hasRoute<NetworkMonitoringRoute>() == true -> false
 currentDestination?.hasRoute<SensorDetailsRoute>() == true -> false
 else -> true
 }
 }
 }

 Scaffold(
 topBar = {
 // App Header with dynamic title
 Box(
 modifier = Modifier
 .fillMaxWidth()
 .background(
 brush = Brush.linearGradient(
 colors = CoreDroidColors.Gradients.SecondaryGradient
 )
 )
 .padding(CoreDroidDimensions.HeaderPadding),
 contentAlignment = Alignment.Center
 ) {
 Column(
 horizontalAlignment = Alignment.CenterHorizontally
 ) {
 Text(
 text = "CoreDroid",
 style = CoreDroidTextStyles.AppTitle,
 color = Color.White
 )
 Text(
 text = currentTitle,
 style = CoreDroidTextStyles.AppSubtitle,
 color = Color.White.copy(alpha = 0.9f)
 )
 }
 }
 },
 bottomBar = {
 if (shouldShowBottomBar) {
 BottomNavigationBar(
 items = bottomNavItems,
 currentDestination = currentDestination,
 onItemClick = { route ->
 navController.navigate(route) {
 popUpTo(navController.graph.startDestinationId) {
 saveState = true
 }
 launchSingleTop = true
 restoreState = true
 }
 }
 )
 }
 }
 ) { paddingValues ->
 Box(
 modifier = Modifier
 .fillMaxSize()
 .padding(paddingValues)
 .background(MaterialTheme.colorScheme.background)
 ) {
 AppNavigationGraph(navController = navController)
 }
 }
}

@Composable
private fun BottomNavigationBar(
 items: List<BottomNavItem>,
 currentDestination: androidx.navigation.NavDestination?,
 onItemClick: (Any) -> Unit
) {
 NavigationBar {
 items.forEach { item ->
 val isSelected = currentDestination?.hasRoute(item.route::class) == true

 NavigationBarItem(
 selected = isSelected,
 onClick = { onItemClick(item.route) },
 icon = {
 Icon(
 imageVector = item.icon,
 contentDescription = item.title
 )
 },
 label = null // Remove labels, show only icons
 )
 }
 }
}

@Composable
private fun AppNavigationGraph(navController: NavHostController) {
 NavHost(
 navController = navController,
 startDestination = OverviewRoute
 ) {
 composable<OverviewRoute> {
 OverviewScreen()
 }

 composable<HardwareRoute> {
 HardwareScreen()
 }

 composable<SystemRoute> {
 SystemScreen()
 }

 composable<NetworkRoute> {
 NetworkScreen(
 onNavigateToMonitoring = {
 navController.navigate(NetworkMonitoringRoute)
 }
 )
 }

 composable<NetworkMonitoringRoute> {
 NetworkMonitoringScreen(
 onNavigateBack = {
 navController.popBackStack()
 }
 )
 }

 composable<SensorsRoute> {
 SensorsScreen(
 onNavigateToSensorDetails = { sensorType, sensorName ->
 navController.navigate(
 SensorDetailsRoute(
 sensorType = sensorType,
 sensorName = sensorName
 )
 )
 }
 )
 }

 composable<SensorDetailsRoute> { backStackEntry ->
 val route = backStackEntry.toRoute<SensorDetailsRoute>()

 SensorDetailsScreen(
 sensorType = route.sensorType,
 sensorName = route.sensorName,
 onNavigateBack = {
 navController.popBackStack()
 }
 )
 }
 }
}
