@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun NetworkMonitoringScreen(
 onNavigateBack: () -> Unit,
 viewModel: NetworkViewModel = koinViewModel()
) {
 val state by viewModel.state.collectAsState()
 val context = LocalContext.current

 // Handle effects
 LaunchedEffect(Unit) {
 viewModel.effect.collect { effect ->
 when (effect) {
 is NetworkContract.Effect.ShowError -> {
 Toast.makeText(context, effect.message, Toast.LENGTH_LONG).show()
 }

 is NetworkContract.Effect.ShowMonitoringStarted -> {
 Toast.makeText(context, "Real-time monitoring started", Toast.LENGTH_SHORT)
 .show()
 }

 is NetworkContract.Effect.ShowMonitoringStopped -> {
 Toast.makeText(context, "Monitoring stopped", Toast.LENGTH_SHORT).show()
 }

 else -> {}
 }
 }
 }

 // Auto-start monitoring when screen opens
 LaunchedEffect(Unit) {
 if (!state.isMonitoring) {
 viewModel.handleIntent(NetworkContract.Intent.StartMonitoring)
 }
 }

 Scaffold(
 topBar = {
 TopAppBar(
 modifier = Modifier.fillMaxWidth(),
 currentTitle = "Network Monitoring",
 navigationIcon = {
 IconButton(onClick = onNavigateBack) {
 Icon(
 imageVector = Icons.Default.ArrowBack,
 contentDescription = "Back",
 tint = MaterialTheme.colorScheme.primary
 )
 }
 }
 )
 },
 bottomBar = {
 // Always show this at the bottom of the screen
 Button(
 onClick = {
 if (state.isMonitoring) {
 viewModel.handleIntent(NetworkContract.Intent.StopMonitoring)
 } else {
 viewModel.handleIntent(NetworkContract.Intent.StartMonitoring)
 }
 },
 modifier = Modifier
 .fillMaxWidth()
 .padding(CoreDroidDimensions.ScreenPadding),
 shape = MaterialTheme.shapes.medium
 ) {
 Text(if (state.isMonitoring) "Stop Monitoring" else "Start Monitoring")
 }
 }
 ) { paddingValues ->
 Column(
 modifier = Modifier
 .fillMaxSize()
 .verticalScroll(rememberScrollState())
 .padding(paddingValues)
 .padding(horizontal = CoreDroidDimensions.ScreenPadding),
 verticalArrangement = Arrangement.spacedBy(CoreDroidDimensions.SpaceLarge)
 ) {
 // Live Status Banner
 LiveMonitoringBanner(isMonitoring = state.isMonitoring)

 // Current Network Status
 if (state.networkInfoState.isSuccess) {
 val networkInfo = state.networkInfoState.getDataOrNull()!!

 NetworkStatusCard(networkInfo)

 // Network Information Cards (Condensed)
 Row(
 modifier = Modifier.fillMaxWidth(),
 horizontalArrangement = Arrangement.spacedBy(CoreDroidDimensions.SpaceSmall)
 ) {
 MobileCard(
 networkInfo = networkInfo,
 phonePermissionState = state.phonePermissionState,
 modifier = Modifier.weight(1f)
 )
 WifiCard(
 networkInfo = networkInfo,
 modifier = Modifier.weight(1f)
 )
 }
 }

 // Events List (Main focus)
 NetworkEventsCard(
 events = state.monitoringEvents,
 onClearEvents = {
 viewModel.handleIntent(NetworkContract.Intent.ClearMonitoringEvents)
 }
 )
 }
 }
}

@Composable
private fun LiveMonitoringBanner(isMonitoring: Boolean) {
 Card(
 modifier = Modifier.fillMaxWidth(),
 colors = CardDefaults.cardColors(
 containerColor = if (isMonitoring) {
 MaterialTheme.colorScheme.primaryContainer
 } else {
 MaterialTheme.colorScheme.errorContainer
 }
 ),
 elevation = CardDefaults.cardElevation(defaultElevation = CoreDroidDimensions.ElevationSmall)
 ) {
 Row(
 modifier = Modifier.padding(CoreDroidDimensions.SpaceMedium),
 verticalAlignment = Alignment.CenterVertically,
 horizontalArrangement = Arrangement.spacedBy(CoreDroidDimensions.SpaceSmall)
 ) {
 // Status indicator
 Box(
 modifier = Modifier
 .size(16.dp)
 .clip(CircleShape)
 .background(
 if (isMonitoring) {
 MaterialTheme.colorScheme.primary
 } else {
 MaterialTheme.colorScheme.error
 }
 )
 )

 Text(
 text = if (isMonitoring) " LIVE MONITORING ACTIVE" else "⚫ MONITORING STOPPED",
 style = MaterialTheme.typography.titleMedium,
 fontWeight = FontWeight.Bold,
 color = if (isMonitoring) {
 MaterialTheme.colorScheme.onPrimaryContainer
 } else {
 MaterialTheme.colorScheme.onErrorContainer
 }
 )

 Spacer(modifier = Modifier.weight(1f))

 Text(
 text = if (isMonitoring) "Tracking changes..." else "Idle",
 style = MaterialTheme.typography.bodyMedium,
 color = if (isMonitoring) {
 MaterialTheme.colorScheme.onPrimaryContainer.copy(alpha = 0.8f)
 } else {
 MaterialTheme.colorScheme.onErrorContainer.copy(alpha = 0.8f)
 }
 )
 }
 }
}

@Composable
private fun NetworkStatusCard(networkInfo: com.sultonuzdev.coredroid.domain.model.NetworkInfo) {
 InfoCard(

 ) {
 Text(
 text = " Current Network Status",
 style = MaterialTheme.typography.titleMedium,
 color = MaterialTheme.colorScheme.onSurface
 )

 Spacer(modifier = Modifier.height(CoreDroidDimensions.SpaceSmall))

 Row(
 modifier = Modifier.fillMaxWidth(),
 horizontalArrangement = Arrangement.spacedBy(CoreDroidDimensions.GridSpacing)
 ) {
 Column(modifier = Modifier.weight(1f)) {
 InfoRow("WiFi", if (networkInfo.isWifiConnected) "Connected" else "Disconnected")
 InfoRow(
 "Mobile",
 if (networkInfo.isMobileConnected) "Connected" else "Disconnected"
 )
 }
 Column(modifier = Modifier.weight(1f)) {
 InfoRow("IP Address", networkInfo.ipAddress)
 InfoRow("Network Type", networkInfo.networkType)
 }
 }
 }
}

@Composable
private fun MonitoringControlsCard(
 isMonitoring: Boolean,
 onStartMonitoring: () -> Unit,
 onStopMonitoring: () -> Unit
) {
 Card(
 modifier = Modifier.fillMaxWidth(),
 elevation = CardDefaults.cardElevation(defaultElevation = CoreDroidDimensions.ElevationMedium)
 ) {
 Column(
 modifier = Modifier.padding(CoreDroidDimensions.CardPadding),
 verticalArrangement = Arrangement.spacedBy(CoreDroidDimensions.SpaceSmall)
 ) {
 Text(
 text = "⚙️ Monitoring Controls",
 style = MaterialTheme.typography.titleMedium,
 color = MaterialTheme.colorScheme.onSurface
 )

 Row(
 modifier = Modifier.fillMaxWidth(),
 horizontalArrangement = Arrangement.spacedBy(CoreDroidDimensions.SpaceSmall)
 ) {
 Button(
 onClick = if (isMonitoring) onStopMonitoring else onStartMonitoring,
 modifier = Modifier.weight(1f)
 ) {
 Text(if (isMonitoring) "Stop Monitoring" else "Start Monitoring")
 }
 }
 }
 }
}

@Composable
private fun NetworkEventsCard(
 events: List<NetworkContract.MonitoringEvent>,
 onClearEvents: () -> Unit
) {
 Card(
 modifier = Modifier.fillMaxWidth(),
 elevation = CardDefaults.cardElevation(defaultElevation = CoreDroidDimensions.ElevationMedium)
 ) {
 Column(
 modifier = Modifier.padding(CoreDroidDimensions.CardPadding)
 ) {
 Row(
 modifier = Modifier.fillMaxWidth(),
 horizontalArrangement = Arrangement.SpaceBetween,
 verticalAlignment = Alignment.CenterVertically
 ) {
 Text(
 text = " Network Events (${events.size})",
 style = MaterialTheme.typography.titleMedium,
 color = MaterialTheme.colorScheme.onSurface
 )

 if (events.isNotEmpty()) {
 OutlinedButton(
 onClick = onClearEvents,
 modifier = Modifier.height(32.dp)
 ) {
 Text(
 text = "Clear All",
 style = MaterialTheme.typography.bodySmall
 )
 }
 }
 }

 Spacer(modifier = Modifier.height(CoreDroidDimensions.SpaceSmall))

 if (events.isEmpty()) {
 Box(
 modifier = Modifier
 .fillMaxWidth()
 .height(200.dp),
 contentAlignment = Alignment.Center
 ) {
 Column(
 horizontalAlignment = Alignment.CenterHorizontally,
 verticalArrangement = Arrangement.spacedBy(CoreDroidDimensions.SpaceSmall)
 ) {
 Text(
 text = "",
 style = MaterialTheme.typography.headlineLarge
 )
 Text(
 text = "No network events yet",
 style = MaterialTheme.typography.bodyLarge,
 color = MaterialTheme.colorScheme.onSurfaceVariant
 )
 Text(
 text = "Network changes will appear here when monitoring is active",
 style = MaterialTheme.typography.bodySmall,
 color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.7f)
 )
 }
 }
 } else {
 LazyColumn(
 modifier = Modifier.height(300.dp),
 verticalArrangement = Arrangement.spacedBy(CoreDroidDimensions.SpaceXSmall)
 ) {
 items(events.reversed()) { event ->
 NetworkEventItem(event = event)
 }
 }
 }
 }
 }
}

@Composable
private fun NetworkEventItem(event: NetworkContract.MonitoringEvent) {
 val timeFormat = SimpleDateFormat("HH:mm:ss", Locale.getDefault())

 Card(
 modifier = Modifier.fillMaxWidth(),
 colors = CardDefaults.cardColors(
 containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f)
 ),
 shape = RoundedCornerShape(8.dp)
 ) {
 Row(
 modifier = Modifier.padding(CoreDroidDimensions.SpaceSmall),
 verticalAlignment = Alignment.CenterVertically
 ) {
 Text(
 text = timeFormat.format(Date(event.timestamp)),
 style = MaterialTheme.typography.bodySmall,
 color = MaterialTheme.colorScheme.primary,
 fontWeight = FontWeight.Medium,
 modifier = Modifier.width(60.dp)
 )

 Spacer(modifier = Modifier.width(CoreDroidDimensions.SpaceSmall))

 Card(
 colors = CardDefaults.cardColors(
 containerColor = when (event.type) {
 "WIFI" -> CoreDroidColors.Success.copy(alpha = 0.2f)
 "MOBILE" -> CoreDroidColors.Warning.copy(alpha = 0.2f)
 "STATUS" -> CoreDroidColors.Primary.copy(alpha = 0.2f)
 "SIGNAL" -> CoreDroidColors.Info.copy(alpha = 0.2f)
 "ERROR" -> CoreDroidColors.Error.copy(alpha = 0.2f)
 else -> MaterialTheme.colorScheme.surfaceVariant
 }
 ),
 shape = RoundedCornerShape(4.dp)
 ) {
 Text(
 text = event.type,
 style = MaterialTheme.typography.bodySmall,
 fontWeight = FontWeight.Medium,
 color = MaterialTheme.colorScheme.onSurfaceVariant,
 modifier = Modifier.padding(horizontal = 8.dp, vertical = 2.dp)
 )
 }

 Spacer(modifier = Modifier.width(CoreDroidDimensions.SpaceSmall))

 Text(
 text = event.description,
 style = MaterialTheme.typography.bodySmall,
 color = MaterialTheme.colorScheme.onSurfaceVariant,
 modifier = Modifier.weight(1f)
 )
 }
 }
